@layer hj.components {
  /* Customise: --hj-checkbox-size · --hj-checkbox-radius */
  .hj-checkbox {
    --_s: var(--hj-checkbox-size, 22px);
    position: relative;
    display: inline-grid;
    flex: none;
    place-items: center;
    width: var(--_s);
    height: var(--_s);
    border-radius: var(--hj-checkbox-radius, calc(var(--hj-radius-xs) - 2px));
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--hj-fg) 26%, transparent);
    color: var(--hj-on-accent);
    vertical-align: middle;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      box-shadow var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  /* 44px hit area around a 22px drawing */
  .hj-checkbox::before {
    content: '';
    position: absolute;
    inset: calc((var(--_s) - var(--hj-touch)) / 2);
  }
  .hj-checkbox[data-size='sm'] {
    --_s: var(--hj-checkbox-size, 18px);
  }
  .hj-checkbox:hover:not([data-disabled]):not([data-checked]):not([data-indeterminate]) {
    box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--hj-fg) 44%, transparent);
  }
  .hj-checkbox:active:not([data-disabled]) {
    transform: scale(0.92);
    transition-duration: var(--hj-dur-fast), var(--hj-dur-fast), 70ms;
  }
  .hj-checkbox[data-checked],
  .hj-checkbox[data-indeterminate] {
    background: var(--hj-accent);
    box-shadow: inset 0 0 0 1.5px transparent;
  }
  .hj-checkbox[data-invalid]:not([data-checked]) {
    box-shadow: inset 0 0 0 1.5px var(--hj-danger);
  }
  .hj-checkbox[data-disabled] {
    opacity: 0.4;
    cursor: not-allowed;
  }
  .hj-checkbox[data-readonly] {
    cursor: default;
  }

  .hj-checkbox-indicator {
    display: block;
    width: 100%;
    height: 100%;
  }
  .hj-checkbox-indicator svg {
    display: block;
  }
  .hj-checkbox-indicator path {
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
    /* leaving: quick and un-drawn backwards */
    transition: stroke-dashoffset var(--hj-dur-fast) var(--hj-ease-out);
  }
  /* The tick draws itself: a settled spring, so it never overshoots the corner. */
  .hj-checkbox-indicator[data-checked]:not([data-indeterminate]) path[data-mark='check'],
  .hj-checkbox-indicator[data-indeterminate] path[data-mark='dash'] {
    stroke-dashoffset: 0;
    transition: stroke-dashoffset var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle) 40ms;
  }
}

'use client';
import { Checkbox as Base } from '@base-ui/react/checkbox';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { cls, withDefaults } from '../../system/slot.ts';

/** The tick and the dash, drawn on a 22-grid so they can draw themselves (pathLength = 1). */
function Marks(): React.ReactElement {
  return (
    <svg
      viewBox="0 0 22 22"
      width="100%"
      height="100%"
      fill="none"
      aria-hidden="true"
      focusable="false"
    >
      <path data-mark="check" d="M6 11.4 9.4 14.8 16 8" pathLength={1} />
      <path data-mark="dash" d="M6.5 11h9" pathLength={1} />
    </svg>
  );
}

export interface IndicatorProps extends Base.Indicator.Props {}

/**
 * The tick. Kept mounted so it can draw itself in and out; renders hanji's tick and dash when
 * given no children (pass your own icon to replace them).
 */
export function Indicator(props: IndicatorProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    className,
    children,
    keepMounted = true,
    ...rest
  } = withDefaults(config, 'Checkbox.Indicator', props);
  return (
    <Base.Indicator
      {...rest}
      keepMounted={keepMounted}
      className={cls(config, 'Checkbox.Indicator', 'hj-checkbox-indicator', className)}
    >
      {children ?? <Marks />}
    </Base.Indicator>
  );
}

export interface RootOwnProps {
  /** md = 22 (hanji), sm = 18. */
  size?: 'sm' | 'md';
}
export interface RootProps extends RootOwnProps, Base.Root.Props {}

/**
 * A box you tick for a choice that waits for a Save. Renders its Indicator when given no
 * children, so `<Checkbox.Root />` is complete. Label it by wrapping in a `<label>` or a Field.
 */
export function Root(props: RootProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    size = 'md',
    className,
    children,
    ...rest
  } = withDefaults(config, 'Checkbox.Root', props);
  return (
    <Base.Root
      {...rest}
      data-size={size}
      className={cls(config, 'Checkbox.Root', 'hj-checkbox', className)}
    >
      {children ?? <Indicator />}
    </Base.Root>
  );
}

export * as Checkbox from './checkbox.tsx';
export type {
  IndicatorProps as CheckboxIndicatorProps,
  RootOwnProps as CheckboxRootOwnProps,
  RootProps as CheckboxRootProps,
} from './checkbox.tsx';
